def has_close_elements(numbers: List[float], threshold: float) -> bool:
    for i in range(len(numbers)):
        for j in range(i + 1, len(numbers)):
            if abs(numbers[i] - numbers[j]) < threshold:
                return True
    return False

def separate_paren_groups(paren_string: str) -> List[str]:
    result = []
    current_group = []
    depth = 0

    for char in paren_string.replace(" ", ""):
        if char == '(':
            depth += 1
        current_group.append(char)
        if char == ')':
            depth -= 1
            if depth == 0:
                result.append(''.join(current_group))
                current_group = []

    return result

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for operation in operations:
        balance += operation
        if balance < 0:
            return True
    return False

def find_topmost_carpet(n, carpets, point) -> int:
    x, y = point
    topmost_carpet = -1

    for i in range(n):
        a, b, g, k = carpets[i]
        if a <= x <= a + g and b <= y <= b + k:
            if topmost_carpet == -1 or i > topmost_carpet:
                topmost_carpet = i

    return topmost_carpet

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    grid = [[0] * N for _ in range(N)]
    for x, y, value in grid_values:
        if x != 0 or y != 0 or value != 0:
            grid[x - 1][y - 1] = value

    dp = [[[-float('inf')] * 2 for _ in range(N)] for _ in range(N)]
    dp[0][0][0] = grid[0][0]

    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                continue
            value = grid[i][j]
            dp[i][j][0] = max(dp[i][j][0], dp[i-1][j][0] + value) if i > 0 else -float('inf')
            dp[i][j][0] = max(dp[i][j][0], dp[i][j-1][0] + value) if j > 0 else -float('inf')
            dp[i][j][1] = max(dp[i][j][1], dp[i-1][j][1] + value) if i > 0 else -float('inf')
            dp[i][j][1] = max(dp[i][j][1], dp[i][j-1][1] + value) if j > 0 else -float('inf')
            dp[i][j][1] = max(dp[i][j][1], dp[i-1][j][0] + value) if i > 0 else -float('inf')
            dp[i][j][1] = max(dp[i][j][1], dp[i][j-1][0] + value) if j > 0 else -float('inf')
            dp[i][j][1] = max(dp[i][j][1], dp[i-1][j][1] + value) if i > 0 and j > 0 else -float('inf')
            dp[i][j][1] = max(dp[i][j][1], dp[i][j-1][1] + value) if i > 0 and j > 0 else -float('inf')

    return max(dp[N-1][N-1])

