def cantor_numbering(N: int) -> str:
    diagonal = 1
    while N > diagonal * (diagonal + 1) // 2:
        N -= diagonal * (diagonal + 1) // 2
        diagonal += 1

    row = diagonal - N + 1
    col = N - (diagonal - row)

    if diagonal % 2 == 0:
        return f"{col}/{row}"
    else:
        return f"{row}/{col}"

