def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> int:
        total = 0
        for i, char in enumerate(isbn):
            if char.isdigit():
                total += int(char) * (10 - i)
            elif char == 'X':
                total += 10 * (10 - i)
        return total % 11

    parts = isbn.split('-')
    if len(parts) != 5 or parts[0] == '' or parts[1] == '' or parts[2] == '' or parts[3] == '' or parts[4] == '':
        return "Invalid ISBN format"

    isbn_number = parts[3] + parts[4].replace('X', '10')
    expected_checksum = calculate_checksum(isbn_number)

    if expected_checksum == 0:
        return isbn
    else:
        return "Right"

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    row_sep_count = [0] * (M + 1)
    col_sep_count = [0] * (N + 1)

    for (Xi, Yi, Pi, Qi) in chatting_pairs:
        if Xi == Pi:  # Same row
            col_sep = min(Yi, Qi) + 1
            if col_sep > 0 and col_sep < N:
                col_sep_count[col_sep] += 1
        elif Yi == Qi:  # Same column
            row_sep = min(Xi, Pi) + 1
            if row_sep > 0 and row_sep < M:
                row_sep_count[row_sep] += 1

    selected_rows = []
    selected_cols = []

    for i in range(1, M + 1):
        if row_sep_count[i] > 0:
            selected_rows.append(i)

    for i in range(1, N + 1):
        if col_sep_count[i] > 0:
            selected_cols.append(i)

    return ' '.join(map(str, selected_rows)), ' '.join(map(str, selected_cols))

def count_passing_ways(n: int, m: int) -> int:
    if n == 0 or m == 0:
        return 0

    dp = [[0] * (m + 1) for _ in range(n)]
    dp[0][0] = 1

    for i in range(1, m + 1):
        dp[0][i] = dp[n-1][i-1]
        dp[n-1][i] = dp[0][i-1]
        for j in range(1, n-1):
            dp[j][i] = dp[j-1][i-1] + dp[j+1][i-1]

    return dp[0][m]

def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    dp = [0] * (n + 1)
    for price, importance in items:
        for j in range(n, price - 1, -1):
            dp[j] = max(dp[j], dp[j - price] + importance)
    return dp[n]

def max_energy(beads):
    n = len(beads)
    dp = [[0] * n for _ in range(n)]

    for gap in range(n):
        for i in range(n - gap):
            j = (i + gap) % n
            for k in range(i, j):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j] + beads[i] * beads[k] * beads[j])

    return dp[0][n - 1]

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i in range(n, -1, -1):
        coeff = coeffs[n - i]
        if coeff == 0:
            continue
        sign = '-' if coeff < 0 else '+' if terms else ''
        abs_coeff = abs(coeff)
        var_part = ''
        if i > 1:
            var_part = f'x^{i}'
        elif i == 1:
            var_part = 'x'
        if abs_coeff != 1 or not var_part:
            var_part = f'{abs_coeff}{var_part}'
        terms.append(f'{sign}{var_part}')
    return ''.join(terms).lstrip('+')

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping and mapping[e] != o:
            return "Failed"
        mapping[e] = o

    if len(mapping) < 26:
        return "Failed"

    decoded = ''.join(mapping.get(c, c) for c in message)
    return decoded

def largest_prime_factor(n: int) -> int:
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return n // i
    return n

def count_partitions(n: int, k: int, x: int) -> int:
    if n < k * x:
        return 0
    if k == 1:
        return 1
    return sum(count_partitions(n - i, k - 1, i) for i in range(x, n // k + 1))

def count_sequences(n: int, last: int, memo: dict) -> int:
    if last == 0:
        return 0
    if last in memo:
        return memo[last]
    count = 0
    for i in range(1, (last // 2) + 1):
        count += count_sequences(n, i, memo)
    memo[last] = count
    return count

def count_coprime_pairs(x0: int, y0: int) -> int:
    from math import gcd
    count = 0
    for a in range(1, y0 // x0 + 1):
        if y0 // x0 % a == 0:
            b = y0 // x0 // a
            if gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
    return count

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    queue = deque([(A, 0)])
    visited = set(A)

    while queue:
        current, steps = queue.popleft()
        if current == B:
            return steps
        if steps >= 10:
            continue
        for src, tgt in rules:
            if src in current:
                index = current.find(src)
                new_str = current[:index] + tgt + current[index + len(src):]
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))

    return "NO ANSWER!"

def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_numbers(n, rules) -> int:
    queue = deque([str(n)])
    visited = set(queue)

    while queue:
        current = queue.popleft()
        for i in range(len(current)):
            for x, y in rules:
                if current[i] == str(x):
                    new_number = current[:i] + str(y) + current[i+1:]
                    if new_number not in visited:
                        visited.add(new_number)
                        queue.append(new_number)

    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    def is_liar(participant: str) -> bool:
        return participant in liar_count

    def is_truthful(participant: str) -> bool:
        return not is_liar(participant)

    for participant, participant_statements in statements.items():
        for statement in participant_statements:
            if statement.startswith("I am"):
                if participant == scenario:
                    if is_liar(participant):
                        return False
                else:
                    if is_truthful(participant):
                        return False
            elif "is not" in statement:
                if participant == scenario:
                    if is_truthful(participant):
                        return False
                else:
                    if is_liar(participant):
                        return False
    return True

def calculate_score(system: int, points: str) -> list:
    scores = []
    player_score = 0
    opponent_score = 0
    game_over = False

    for point in points:
        if point == 'W':
            player_score += 1
        else:
            opponent_score += 1

        if abs(player_score - opponent_score) >= 2 and player_score >= system or opponent_score >= system:
            scores.append(f"{player_score}:{opponent_score}")
            player_score = 0
            opponent_score = 0
            game_over = True

