        scores.append(f"{player_score}:{opponent_score}")

    return scores

def catalan_number(n: int) -> int:
    if n == 0:
        return 1

    catalan = [0] * (n + 1)
    catalan[0] = 1

    for i in range(1, n + 1):
        for j in range(i):
            catalan[i] += catalan[j] * catalan[i - j - 1]

    return catalan[n]

def remaining_trees_after_clearing(l: int, areas: List[Tuple[int, int]]) -> int:
    cleared = [0] * (l + 1)
    for start, end in areas:
        cleared[start] += 1
        cleared[end + 1] -= 1
    for i in range(1, l + 1):
        cleared[i] += cleared[i - 1]
    return l - sum(cleared)

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    DP = [0] * (T + 1)
    for t, v in herbs:
        if t <= T:
            for j in range(T, t - 1, -1):
                DP[j] = max(DP[j], DP[j - t] + v)
    return DP[T]

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    dp = [False] * (V + 1)
    dp[0] = True

    for volume in volumes:
        for j in range(V, volume - 1, -1):
            dp[j] = dp[j] or dp[j - volume]

    max_occupied_space = 0
    for i in range(V, -1, -1):
        if dp[i]:
            max_occupied_space = i
            break

    return V - max_occupied_space

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(m + 1):
            for k in range(a[i - 1] + 1):
                if j - k >= 0:
                    dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD

    return dp[n][m]

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    key_length = len(key)
    plaintext = []

    for i, char in enumerate(ciphertext):
        key_char = key[i % key_length]
        key_shift = ord(key_char.upper()) - ord('A')
        decrypted_char = chr(((ord(char.upper()) - ord('A') - key_shift) % 26) + ord('A'))
        plaintext.append(decrypted_char.lower())

    return ''.join(plaintext)

def mod_inverse(a, b):
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    gcd, x, _ = extended_gcd(a, b)
    if gcd != 1:
        return None
    else:
        return x % b

def find_most_unhappy_day(schedule) -> int:
    max_unhappiness = 0
    unhappiest_day = 0

    for day, (school_hours, extra_hours) in enumerate(schedule, start=1):
        total_hours = school_hours + extra_hours
        if total_hours > 8:
            unhappiness = total_hours - 8
            if unhappiness > max_unhappiness:
                max_unhappiness = unhappiness
                unhappiest_day = day

    return unhappiest_day

