def min_groups(w, n, prices):
    prices.sort()
    left, right = 0, n - 1
    groups = 0

    while left <= right:
        if prices[left] + prices[right] <= w:
            left += 1
        right -= 1
        groups += 1

    return groups

def hanoi_double_iterative(n: int) -> int:
    if n <= 0:
        return 0
    result = 0
    for k in range(1, n + 1):
        result += 2 * (2 ** k - 1)
    return result
